-- ===========================================================================
-- RAILVYN — one-file Neon PostgreSQL setup
--
-- RUN IT: Neon Console -> SQL Editor -> paste this whole file -> click "Run".
-- Do not click "Explain": EXPLAIN can only describe a single query and wraps
-- the script in one EXPLAIN, which fails on DDL/transaction statements (the
-- earlier "syntax error at or near \"set\"" came from that mode).
--
-- RE-RUNNABLE: Part 1 drops and recreates the public schema, deleting every
-- table in the public schema of the target database. Use a dedicated
-- demonstration database, never a database with data you want to keep.
--
-- PART 1 — schema: enums, tables, foreign keys, indexes, constraints
-- PART 2 — deterministic demo data: 63 stations, 16 routes, 30 trains,
--          300 runs, 59,700 seats, 100 bookings, waitlist + audit samples
-- PART 3 — bulk generated data: 1,000+ stations, 1,420 trains/routes,
--          9,940 dated runs (daily for the next 7 days), 19,880 coaches,
--          1,351,840 seats plus a dense all-pairs network that connects every
--          station pair, 1,200 bookings, 1,200 waitlist requests, 1,000
--          disruptions and 1,200 audit rows (no duplicate rows)
--
-- Demo accounts (password for every seeded account: RailvynDemo#2026)
--   passenger@railvyn.demo    priya@railvyn.demo     kabir@railvyn.demo
--   operator@railvyn.demo     operator2@railvyn.demo
--   admin@railvyn.demo
--
-- After running: set NEON_DATABASE_URL (pooled connection string) and
-- BETTER_AUTH_SECRET, restart the app, then sign in as admin@railvyn.demo or
-- operator@railvyn.demo to reach the /admin and /operator portals.
--
-- Independent educational demo. Not IRCTC or Indian Railways, no official PNR,
-- simulated payments only. All train, station and booking data is synthetic.
--
-- File is ~7.3 MiB. If the SQL editor refuses it, apply Part 2 only with
-- `pnpm db:seed` (uses NEON_DATABASE_URL), or use
-- psql "$NEON_DATABASE_URL" -f railvyn-neon-setup.sql.
-- Do not also run Drizzle migrations on this database.
-- ===========================================================================

-- ===========================================================================
-- PART 1 — SCHEMA
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- RAILVYN — complete PostgreSQL schema for a fresh database
-- Generated from drizzle/0000_faulty_mephistopheles.sql + drizzle/0001_icy_solo.sql
-- DO NOT apply this to an existing RAILVYN database after Drizzle migrations;
-- choose either versioned Drizzle migrations OR these SQL files for a fresh DB.
-- Apply: psql "$NEON_DATABASE_URL" -f db/fullschema.sql
-- Then:  psql "$NEON_DATABASE_URL" -f db/seed.sql
--
-- This script is re-runnable and safe to paste into the Neon SQL Editor: it
-- drops and recreates the public schema first. That deletes every table in the
-- public schema of the target database, so only use it on a demo database.
-- It contains no psql-only meta-commands and no SET statements, so "Run" works
-- in the Neon SQL Editor ("Explain" cannot execute DDL and will report an
-- error for any multi-statement script).
-- ---------------------------------------------------------------------------

drop schema if exists public cascade;
create schema public;

CREATE TYPE "public"."app_role" AS ENUM('passenger', 'operator', 'admin');
CREATE TYPE "public"."berth_type" AS ENUM('lower', 'middle', 'upper', 'side_lower', 'side_upper', 'seat');
CREATE TYPE "public"."booking_status" AS ENUM('confirmed', 'cancelled');
CREATE TYPE "public"."disruption_severity" AS ENUM('info', 'warning', 'critical');
CREATE TYPE "public"."hold_status" AS ENUM('active', 'converted', 'expired', 'released');
CREATE TYPE "public"."payment_status" AS ENUM('succeeded', 'refunded');
CREATE TYPE "public"."run_status" AS ENUM('scheduled', 'disrupted', 'cancelled', 'completed');
CREATE TYPE "public"."travel_class" AS ENUM('sleeper', 'ac3', 'ac2', 'chair');
CREATE TYPE "public"."waitlist_status" AS ENUM('waiting', 'offered', 'confirmed', 'expired', 'cancelled');
CREATE TABLE "account" (
	"id" text PRIMARY KEY NOT NULL,
	"account_id" text NOT NULL,
	"provider_id" text NOT NULL,
	"user_id" text NOT NULL,
	"access_token" text,
	"refresh_token" text,
	"id_token" text,
	"access_token_expires_at" timestamp with time zone,
	"refresh_token_expires_at" timestamp with time zone,
	"scope" text,
	"password" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone NOT NULL
);

CREATE TABLE "app_settings" (
	"key" text PRIMARY KEY NOT NULL,
	"value" jsonb NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "audit_logs" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"actor_user_id" text,
	"actor_role" text,
	"action" text NOT NULL,
	"entity_type" text NOT NULL,
	"entity_id" text,
	"metadata" jsonb,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "booking_passengers" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"booking_id" uuid NOT NULL,
	"full_name" text NOT NULL,
	"age" integer NOT NULL,
	"gender" text NOT NULL,
	"position" integer NOT NULL,
	CONSTRAINT "booking_passengers_age_valid" CHECK ("booking_passengers"."age" >= 0 AND "booking_passengers"."age" <= 120)
);

CREATE TABLE "booking_seats" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"booking_id" uuid NOT NULL,
	"run_seat_id" uuid NOT NULL,
	"passenger_id" uuid NOT NULL,
	"fare_paise" integer NOT NULL
);

CREATE TABLE "bookings" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"reference" varchar(20) NOT NULL,
	"user_id" text NOT NULL,
	"run_id" uuid NOT NULL,
	"from_stop_index" integer NOT NULL,
	"to_stop_index" integer NOT NULL,
	"travel_class" "travel_class" NOT NULL,
	"passenger_count" integer NOT NULL,
	"total_fare_paise" integer NOT NULL,
	"status" "booking_status" DEFAULT 'confirmed' NOT NULL,
	"contact_email" text NOT NULL,
	"contact_phone" text,
	"idempotency_key" varchar(100) NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"cancelled_at" timestamp with time zone,
	"cancellation_reason" text,
	CONSTRAINT "bookings_valid_range" CHECK ("bookings"."to_stop_index" > "bookings"."from_stop_index"),
	CONSTRAINT "bookings_passenger_count_positive" CHECK ("bookings"."passenger_count" > 0),
	CONSTRAINT "bookings_fare_non_negative" CHECK ("bookings"."total_fare_paise" >= 0)
);

CREATE TABLE "coach_templates" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"code" varchar(16) NOT NULL,
	"name" text NOT NULL,
	"travel_class" "travel_class" NOT NULL,
	"layout_style" text NOT NULL,
	"total_seats" integer NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "coach_templates_total_positive" CHECK ("coach_templates"."total_seats" > 0)
);

CREATE TABLE "disruptions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"run_id" uuid NOT NULL,
	"title" text NOT NULL,
	"description" text NOT NULL,
	"severity" "disruption_severity" DEFAULT 'warning' NOT NULL,
	"created_by" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"resolved_at" timestamp with time zone
);

CREATE TABLE "fares" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"route_id" uuid NOT NULL,
	"travel_class" "travel_class" NOT NULL,
	"from_stop_index" integer NOT NULL,
	"to_stop_index" integer NOT NULL,
	"amount_paise" integer NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "fares_valid_range" CHECK ("fares"."to_stop_index" > "fares"."from_stop_index"),
	CONSTRAINT "fares_amount_non_negative" CHECK ("fares"."amount_paise" >= 0)
);

CREATE TABLE "hold_seats" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"hold_id" uuid NOT NULL,
	"run_seat_id" uuid NOT NULL
);

CREATE TABLE "operator_scopes" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" text NOT NULL,
	"train_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "payments_demo" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"booking_id" uuid NOT NULL,
	"amount_paise" integer NOT NULL,
	"status" "payment_status" DEFAULT 'succeeded' NOT NULL,
	"method" text DEFAULT 'demo_card' NOT NULL,
	"idempotency_key" varchar(120) NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "payments_demo_amount_non_negative" CHECK ("payments_demo"."amount_paise" >= 0)
);

CREATE TABLE "role_assignments" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" text NOT NULL,
	"role" "app_role" NOT NULL,
	"granted_by" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "route_stops" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"route_id" uuid NOT NULL,
	"station_id" uuid NOT NULL,
	"stop_index" integer NOT NULL,
	"distance_km" integer NOT NULL,
	"scheduled_offset_minutes" integer NOT NULL,
	CONSTRAINT "route_stops_index_non_negative" CHECK ("route_stops"."stop_index" >= 0),
	CONSTRAINT "route_stops_distance_non_negative" CHECK ("route_stops"."distance_km" >= 0)
);

CREATE TABLE "routes" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"code" varchar(16) NOT NULL,
	"name" text NOT NULL,
	"description" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "run_coaches" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"run_id" uuid NOT NULL,
	"template_id" uuid NOT NULL,
	"coach_code" varchar(8) NOT NULL,
	"position" integer NOT NULL,
	"travel_class" "travel_class" NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "run_seats" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"run_coach_id" uuid NOT NULL,
	"seat_number" integer NOT NULL,
	"berth_type" "berth_type" NOT NULL,
	"deck" text DEFAULT 'lower' NOT NULL,
	"row_index" integer NOT NULL,
	"position_in_row" integer NOT NULL,
	"is_accessible" boolean DEFAULT false NOT NULL
);

CREATE TABLE "seat_holds" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" text NOT NULL,
	"run_id" uuid NOT NULL,
	"from_stop_index" integer NOT NULL,
	"to_stop_index" integer NOT NULL,
	"travel_class" "travel_class" NOT NULL,
	"passenger_count" integer NOT NULL,
	"status" "hold_status" DEFAULT 'active' NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"idempotency_key" varchar(100) NOT NULL,
	"converted_booking_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "seat_holds_valid_range" CHECK ("seat_holds"."to_stop_index" > "seat_holds"."from_stop_index"),
	CONSTRAINT "seat_holds_passenger_count_positive" CHECK ("seat_holds"."passenger_count" > 0)
);

CREATE TABLE "seat_segment_claims" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"run_seat_id" uuid NOT NULL,
	"segment_index" integer NOT NULL,
	"hold_id" uuid,
	"booking_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "seat_segment_claims_segment_non_negative" CHECK ("seat_segment_claims"."segment_index" >= 0),
	CONSTRAINT "seat_segment_claims_single_owner" CHECK ((CASE WHEN "seat_segment_claims"."hold_id" IS NULL THEN 0 ELSE 1 END) + (CASE WHEN "seat_segment_claims"."booking_id" IS NULL THEN 0 ELSE 1 END) = 1)
);

CREATE TABLE "session" (
	"id" text PRIMARY KEY NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"token" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone NOT NULL,
	"ip_address" text,
	"user_agent" text,
	"user_id" text NOT NULL,
	CONSTRAINT "session_token_unique" UNIQUE("token")
);

CREATE TABLE "stations" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"code" varchar(8) NOT NULL,
	"name" text NOT NULL,
	"city" text NOT NULL,
	"state" text NOT NULL,
	"timezone" text DEFAULT 'Asia/Kolkata' NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "template_seats" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"template_id" uuid NOT NULL,
	"seat_number" integer NOT NULL,
	"berth_type" "berth_type" NOT NULL,
	"deck" text DEFAULT 'lower' NOT NULL,
	"row_index" integer NOT NULL,
	"position_in_row" integer NOT NULL,
	"is_accessible" boolean DEFAULT false NOT NULL,
	CONSTRAINT "template_seats_number_positive" CHECK ("template_seats"."seat_number" > 0)
);

CREATE TABLE "train_runs" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"train_id" uuid NOT NULL,
	"service_date" date NOT NULL,
	"departure_at" timestamp with time zone NOT NULL,
	"arrival_at" timestamp with time zone NOT NULL,
	"status" "run_status" DEFAULT 'scheduled' NOT NULL,
	"notes" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "train_runs_arrival_after_departure" CHECK ("train_runs"."arrival_at" > "train_runs"."departure_at")
);

CREATE TABLE "trains" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"code" varchar(12) NOT NULL,
	"name" text NOT NULL,
	"route_id" uuid NOT NULL,
	"active" boolean DEFAULT true NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "user" (
	"id" text PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"email" text NOT NULL,
	"email_verified" boolean DEFAULT false NOT NULL,
	"image" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "user_email_unique" UNIQUE("email")
);

CREATE TABLE "verification" (
	"id" text PRIMARY KEY NOT NULL,
	"identifier" text NOT NULL,
	"value" text NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE "waitlist_entries" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" text NOT NULL,
	"run_id" uuid NOT NULL,
	"from_stop_index" integer NOT NULL,
	"to_stop_index" integer NOT NULL,
	"travel_class" "travel_class" NOT NULL,
	"passenger_count" integer NOT NULL,
	"priority" integer DEFAULT 0 NOT NULL,
	"status" "waitlist_status" DEFAULT 'waiting' NOT NULL,
	"offered_hold_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "waitlist_valid_range" CHECK ("waitlist_entries"."to_stop_index" > "waitlist_entries"."from_stop_index"),
	CONSTRAINT "waitlist_passenger_count_positive" CHECK ("waitlist_entries"."passenger_count" > 0)
);

ALTER TABLE "account" ADD CONSTRAINT "account_user_id_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."user"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "audit_logs" ADD CONSTRAINT "audit_logs_actor_user_id_user_id_fk" FOREIGN KEY ("actor_user_id") REFERENCES "public"."user"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "booking_passengers" ADD CONSTRAINT "booking_passengers_booking_id_bookings_id_fk" FOREIGN KEY ("booking_id") REFERENCES "public"."bookings"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "booking_seats" ADD CONSTRAINT "booking_seats_booking_id_bookings_id_fk" FOREIGN KEY ("booking_id") REFERENCES "public"."bookings"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "booking_seats" ADD CONSTRAINT "booking_seats_run_seat_id_run_seats_id_fk" FOREIGN KEY ("run_seat_id") REFERENCES "public"."run_seats"("id") ON DELETE restrict ON UPDATE no action;
ALTER TABLE "booking_seats" ADD CONSTRAINT "booking_seats_passenger_id_booking_passengers_id_fk" FOREIGN KEY ("passenger_id") REFERENCES "public"."booking_passengers"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "bookings" ADD CONSTRAINT "bookings_user_id_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."user"("id") ON DELETE restrict ON UPDATE no action;
ALTER TABLE "bookings" ADD CONSTRAINT "bookings_run_id_train_runs_id_fk" FOREIGN KEY ("run_id") REFERENCES "public"."train_runs"("id") ON DELETE restrict ON UPDATE no action;
ALTER TABLE "disruptions" ADD CONSTRAINT "disruptions_run_id_train_runs_id_fk" FOREIGN KEY ("run_id") REFERENCES "public"."train_runs"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "disruptions" ADD CONSTRAINT "disruptions_created_by_user_id_fk" FOREIGN KEY ("created_by") REFERENCES "public"."user"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "fares" ADD CONSTRAINT "fares_route_id_routes_id_fk" FOREIGN KEY ("route_id") REFERENCES "public"."routes"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "hold_seats" ADD CONSTRAINT "hold_seats_hold_id_seat_holds_id_fk" FOREIGN KEY ("hold_id") REFERENCES "public"."seat_holds"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "hold_seats" ADD CONSTRAINT "hold_seats_run_seat_id_run_seats_id_fk" FOREIGN KEY ("run_seat_id") REFERENCES "public"."run_seats"("id") ON DELETE restrict ON UPDATE no action;
ALTER TABLE "operator_scopes" ADD CONSTRAINT "operator_scopes_user_id_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."user"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "operator_scopes" ADD CONSTRAINT "operator_scopes_train_id_trains_id_fk" FOREIGN KEY ("train_id") REFERENCES "public"."trains"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "payments_demo" ADD CONSTRAINT "payments_demo_booking_id_bookings_id_fk" FOREIGN KEY ("booking_id") REFERENCES "public"."bookings"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "role_assignments" ADD CONSTRAINT "role_assignments_user_id_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."user"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "role_assignments" ADD CONSTRAINT "role_assignments_granted_by_user_id_fk" FOREIGN KEY ("granted_by") REFERENCES "public"."user"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "route_stops" ADD CONSTRAINT "route_stops_route_id_routes_id_fk" FOREIGN KEY ("route_id") REFERENCES "public"."routes"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "route_stops" ADD CONSTRAINT "route_stops_station_id_stations_id_fk" FOREIGN KEY ("station_id") REFERENCES "public"."stations"("id") ON DELETE restrict ON UPDATE no action;
ALTER TABLE "run_coaches" ADD CONSTRAINT "run_coaches_run_id_train_runs_id_fk" FOREIGN KEY ("run_id") REFERENCES "public"."train_runs"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "run_coaches" ADD CONSTRAINT "run_coaches_template_id_coach_templates_id_fk" FOREIGN KEY ("template_id") REFERENCES "public"."coach_templates"("id") ON DELETE restrict ON UPDATE no action;
ALTER TABLE "run_seats" ADD CONSTRAINT "run_seats_run_coach_id_run_coaches_id_fk" FOREIGN KEY ("run_coach_id") REFERENCES "public"."run_coaches"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "seat_holds" ADD CONSTRAINT "seat_holds_user_id_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."user"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "seat_holds" ADD CONSTRAINT "seat_holds_run_id_train_runs_id_fk" FOREIGN KEY ("run_id") REFERENCES "public"."train_runs"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "seat_holds" ADD CONSTRAINT "seat_holds_converted_booking_id_bookings_id_fk" FOREIGN KEY ("converted_booking_id") REFERENCES "public"."bookings"("id") ON DELETE set null ON UPDATE no action;
ALTER TABLE "seat_segment_claims" ADD CONSTRAINT "seat_segment_claims_run_seat_id_run_seats_id_fk" FOREIGN KEY ("run_seat_id") REFERENCES "public"."run_seats"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "seat_segment_claims" ADD CONSTRAINT "seat_segment_claims_hold_id_seat_holds_id_fk" FOREIGN KEY ("hold_id") REFERENCES "public"."seat_holds"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "seat_segment_claims" ADD CONSTRAINT "seat_segment_claims_booking_id_bookings_id_fk" FOREIGN KEY ("booking_id") REFERENCES "public"."bookings"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "session" ADD CONSTRAINT "session_user_id_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."user"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "template_seats" ADD CONSTRAINT "template_seats_template_id_coach_templates_id_fk" FOREIGN KEY ("template_id") REFERENCES "public"."coach_templates"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "train_runs" ADD CONSTRAINT "train_runs_train_id_trains_id_fk" FOREIGN KEY ("train_id") REFERENCES "public"."trains"("id") ON DELETE restrict ON UPDATE no action;
ALTER TABLE "trains" ADD CONSTRAINT "trains_route_id_routes_id_fk" FOREIGN KEY ("route_id") REFERENCES "public"."routes"("id") ON DELETE restrict ON UPDATE no action;
ALTER TABLE "waitlist_entries" ADD CONSTRAINT "waitlist_entries_user_id_user_id_fk" FOREIGN KEY ("user_id") REFERENCES "public"."user"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "waitlist_entries" ADD CONSTRAINT "waitlist_entries_run_id_train_runs_id_fk" FOREIGN KEY ("run_id") REFERENCES "public"."train_runs"("id") ON DELETE cascade ON UPDATE no action;
ALTER TABLE "waitlist_entries" ADD CONSTRAINT "waitlist_entries_offered_hold_id_seat_holds_id_fk" FOREIGN KEY ("offered_hold_id") REFERENCES "public"."seat_holds"("id") ON DELETE set null ON UPDATE no action;
CREATE INDEX "account_user_id_idx" ON "account" USING btree ("user_id");
CREATE INDEX "audit_logs_created_idx" ON "audit_logs" USING btree ("created_at");
CREATE INDEX "audit_logs_entity_idx" ON "audit_logs" USING btree ("entity_type","entity_id");
CREATE INDEX "booking_passengers_booking_idx" ON "booking_passengers" USING btree ("booking_id");
CREATE UNIQUE INDEX "booking_seats_booking_seat_unique" ON "booking_seats" USING btree ("booking_id","run_seat_id");
CREATE UNIQUE INDEX "booking_seats_passenger_unique" ON "booking_seats" USING btree ("passenger_id");
CREATE INDEX "booking_seats_booking_idx" ON "booking_seats" USING btree ("booking_id");
CREATE UNIQUE INDEX "bookings_reference_unique" ON "bookings" USING btree ("reference");
CREATE UNIQUE INDEX "bookings_idempotency_unique" ON "bookings" USING btree ("idempotency_key");
CREATE INDEX "bookings_user_created_idx" ON "bookings" USING btree ("user_id","created_at");
CREATE INDEX "bookings_run_idx" ON "bookings" USING btree ("run_id");
CREATE UNIQUE INDEX "coach_templates_code_unique" ON "coach_templates" USING btree ("code");
CREATE INDEX "disruptions_run_idx" ON "disruptions" USING btree ("run_id");
CREATE UNIQUE INDEX "fares_route_class_pair_unique" ON "fares" USING btree ("route_id","travel_class","from_stop_index","to_stop_index");
CREATE UNIQUE INDEX "hold_seats_hold_seat_unique" ON "hold_seats" USING btree ("hold_id","run_seat_id");
CREATE INDEX "hold_seats_hold_idx" ON "hold_seats" USING btree ("hold_id");
CREATE UNIQUE INDEX "operator_scopes_user_train_unique" ON "operator_scopes" USING btree ("user_id","train_id");
CREATE INDEX "operator_scopes_user_idx" ON "operator_scopes" USING btree ("user_id");
CREATE UNIQUE INDEX "payments_demo_booking_unique" ON "payments_demo" USING btree ("booking_id");
CREATE UNIQUE INDEX "payments_demo_idempotency_unique" ON "payments_demo" USING btree ("idempotency_key");
CREATE UNIQUE INDEX "role_assignments_user_role_unique" ON "role_assignments" USING btree ("user_id","role");
CREATE INDEX "role_assignments_user_idx" ON "role_assignments" USING btree ("user_id");
CREATE UNIQUE INDEX "route_stops_route_index_unique" ON "route_stops" USING btree ("route_id","stop_index");
CREATE UNIQUE INDEX "route_stops_route_station_unique" ON "route_stops" USING btree ("route_id","station_id");
CREATE UNIQUE INDEX "routes_code_unique" ON "routes" USING btree ("code");
CREATE UNIQUE INDEX "run_coaches_run_code_unique" ON "run_coaches" USING btree ("run_id","coach_code");
CREATE UNIQUE INDEX "run_coaches_run_position_unique" ON "run_coaches" USING btree ("run_id","position");
CREATE INDEX "run_coaches_run_idx" ON "run_coaches" USING btree ("run_id");
CREATE UNIQUE INDEX "run_seats_coach_number_unique" ON "run_seats" USING btree ("run_coach_id","seat_number");
CREATE INDEX "run_seats_coach_idx" ON "run_seats" USING btree ("run_coach_id");
CREATE UNIQUE INDEX "seat_holds_idempotency_unique" ON "seat_holds" USING btree ("idempotency_key");
CREATE INDEX "seat_holds_status_expiry_idx" ON "seat_holds" USING btree ("status","expires_at");
CREATE INDEX "seat_holds_run_idx" ON "seat_holds" USING btree ("run_id");
CREATE INDEX "seat_holds_user_idx" ON "seat_holds" USING btree ("user_id");
CREATE UNIQUE INDEX "seat_segment_claims_seat_segment_unique" ON "seat_segment_claims" USING btree ("run_seat_id","segment_index");
CREATE INDEX "seat_segment_claims_hold_idx" ON "seat_segment_claims" USING btree ("hold_id");
CREATE INDEX "seat_segment_claims_booking_idx" ON "seat_segment_claims" USING btree ("booking_id");
CREATE INDEX "session_user_id_idx" ON "session" USING btree ("user_id");
CREATE UNIQUE INDEX "stations_code_unique" ON "stations" USING btree ("code");
CREATE UNIQUE INDEX "template_seats_template_number_unique" ON "template_seats" USING btree ("template_id","seat_number");
CREATE UNIQUE INDEX "train_runs_train_date_unique" ON "train_runs" USING btree ("train_id","service_date");
CREATE INDEX "train_runs_service_date_idx" ON "train_runs" USING btree ("service_date");
CREATE UNIQUE INDEX "trains_code_unique" ON "trains" USING btree ("code");
CREATE INDEX "verification_identifier_idx" ON "verification" USING btree ("identifier");
CREATE INDEX "waitlist_run_queue_idx" ON "waitlist_entries" USING btree ("run_id","travel_class","status","priority","created_at");
CREATE INDEX "waitlist_user_idx" ON "waitlist_entries" USING btree ("user_id");
ALTER TABLE "seat_holds" ADD COLUMN "passenger_draft" jsonb;

-- ===========================================================================
-- PART 2 — DEMONSTRATION DATA
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- RAILVYN demonstration seed (PostgreSQL / Neon)
-- Generated from the deterministic seed via: pnpm db:sql:export
-- Apply AFTER db/fullschema.sql on a fresh database.
--
-- WARNING: this truncates all RAILVYN application tables.
-- Demo password for every seeded account: RailvynDemo#2026
-- Seat reuse example: coach S1 seat 42 on the next 12451 run, NDLS→CNB
-- and CNB→HWH booked by different passengers.
--
-- Row counts:
--   user: 12
--   account: 12
--   stations: 63
--   routes: 16
--   route_stops: 87
--   trains: 30
--   train_runs: 300
--   coach_templates: 4
--   template_seats: 262
--   run_coaches: 900
--   run_seats: 59700
--   role_assignments: 15
--   operator_scopes: 6
--   fares: 627
--   bookings: 100
--   booking_passengers: 192
--   booking_seats: 192
--   seat_holds: 10
--   hold_seats: 15
--   seat_segment_claims: 464
--   waitlist_entries: 18
--   payments_demo: 100
--   disruptions: 8
--   audit_logs: 20
--   app_settings: 5
-- ---------------------------------------------------------------------------

begin;

truncate table
  "audit_logs",
  "disruptions",
  "payments_demo",
  "waitlist_entries",
  "seat_segment_claims",
  "hold_seats",
  "seat_holds",
  "booking_seats",
  "booking_passengers",
  "bookings",
  "fares",
  "run_seats",
  "run_coaches",
  "template_seats",
  "coach_templates",
  "train_runs",
  "operator_scopes",
  "trains",
  "role_assignments",
  "route_stops",
  "routes",
  "stations",
  "app_settings",
  "verification",
  "account",
  "session",
  "user"
restart identity cascade;
















































































































































































































































































commit;

-- ===========================================================================
-- PART 3 — BULK GENERATED DATA
-- ===========================================================================

-- ===========================================================================
-- RAILVYN — bulk demonstration data (Part 3)
--
-- Adds 1,000+ rows to every operational table on top of db/seed.sql:
--   stations 1,000 · routes 1,420 · route_stops 50,520 · trains 1,420
--   runs 9,940 · coaches 19,880 · seats 1,351,840 · fares 112,000
--   riders 1,000 · bookings 1,200 · claims 1,200 · waitlist 1,200
--   disruptions 1,000 · audit 1,200 · expired holds 1,000
--
-- Every generated route has a train with one departure on each of the next
-- seven days (today .. today+6), so the date picked in search always returns
-- departures. Runs are keyed by train, day and seed date, so re-running the
-- file extends the window instead of duplicating it.
--
-- A dense all-pairs network (420 synthetic corridors built from 20 station
-- blocks) guarantees that every station pair shares at least one route, so
-- any boarding/alighting combination returns trains.
--
-- Everything is generated inside PostgreSQL with generate_series, so this file
-- stays small enough for the Neon SQL Editor. IDs, codes and journeys are
-- deterministic: re-running it is safe (conflicting rows are skipped).
--
-- No row is a duplicate of another: every station has a unique name/city pair,
-- booking and reference values are unique, each rider appears at most once per
-- run in the waitlist, and disruption/audit rows carry a unique sequence.
--
-- Apply AFTER db/seed.sql (it reuses the seeded demo users and coach
-- templates). Run pnpm db:seed:bulk to apply it from a terminal.
-- ===========================================================================

begin;

/* Repair rows written by older versions of this file -------------------
   Re-running the bulk seed must not leave earlier duplicates behind. Only
   rows with this file's deterministic IDs are touched.
   - older seeds reused 30 station names: rewrite the generated stations
   - older seeds queued the same rider twice for one run: drop the extras
   - older seeds repeated disruption and audit rows: rebuild them below
   - older seeds reused 12 passenger names: rewrite the generated passengers */

update stations s
set name = src.name,
    city = src.city,
    state = src.state
from (
  select
    md5('bulk-station:' || i)::uuid as id,
    x.city || ' ' || x.station_type as name,
    x.city,
    x.state
  from generate_series(1, 1000) as i
  cross join lateral (
    select
      (array['Ram','Nan','Vijay','Krishna','Sundar','Dev','Anand','Shiv','Chand','Govind','Hari','Lakshmi','Madhav','Ganga','Yamuna','Kavi','Nava','Raj','Surya','Chandra'])[1 + ((i - 1) / 50)]
        || (array['pur','garh','nagar','patnam','wada','kot','ganj','palli','durg','khera'])[1 + (((i - 1) / 5) % 10)] as city,
      (array['Junction','Central','Halt','Road','Terminus'])[1 + ((i - 1) % 5)] as station_type,
      (array['Delhi','Maharashtra','Karnataka','Tamil Nadu','West Bengal','Gujarat','Rajasthan','Uttar Pradesh','Telangana','Bihar'])[1 + (((i - 1) / 50) % 10)] as state
  ) as x
) as src
where s.id = src.id
  and (s.name <> src.name or s.city <> src.city or s.state <> src.state);

delete from seat_segment_claims
where booking_id in (
  select md5('bulk-booking:' || i)::uuid from generate_series(1001, 1200) as i
);

delete from payments_demo
where booking_id in (
  select md5('bulk-booking:' || i)::uuid from generate_series(1001, 1200) as i
);

delete from booking_seats
where booking_id in (
  select md5('bulk-booking:' || i)::uuid from generate_series(1001, 1200) as i
);

delete from booking_passengers
where booking_id in (
  select md5('bulk-booking:' || i)::uuid from generate_series(1001, 1200) as i
);

delete from bookings
where id in (
  select md5('bulk-booking:' || i)::uuid from generate_series(1001, 1200) as i
);

delete from waitlist_entries
where id in (
  select md5('bulk-wait:' || i)::uuid from generate_series(1001, 1200) as i
);

delete from disruptions
where id in (
  select md5('bulk-disruption:' || i)::uuid from generate_series(1, 1200) as i
);

delete from audit_logs
where id in (
  select md5('bulk-audit:' || i)::uuid from generate_series(1, 1200) as i
);

update booking_passengers bp
set full_name = src.full_name,
    age = src.age,
    gender = src.gender
from (
  select
    md5('bulk-bp:' || i)::uuid as id,
    (array['Aarav','Vivaan','Aditya','Vihaan','Arjun','Sai','Reyansh','Ayaan','Krishna','Ishaan','Shaurya','Atharv','Advik','Pranav','Dhruv','Kabir','Ritvik','Aarush','Kayaan','Darsh','Rudra','Yash','Vedant','Abhinav','Ananya','Diya','Aadhya','Saanvi','Myra','Anika','Navya','Kiara','Aarohi','Ira','Riya','Sara','Nisha','Meera','Kavya','Ishita'])[1 + ((i - 1) % 40)]
      || ' ' ||
    (array['Sharma','Verma','Nair','Rao','Menon','Iyer','Patel','Reddy','Gupta','Singh','Khan','Bose','Kulkarni','Yadav','Mehta','Joshi','Chopra','Desai','Malhotra','Das','Pillai','Shah','Kapoor','Mishra','Ghosh','Shetty','Trivedi','Banerjee','Chauhan','Naidu'])[1 + (((i - 1) / 40) % 30)] as full_name,
    18 + (i % 55) as age,
    case when ((i - 1) % 40) >= 24 then 'female' else 'male' end as gender
  from generate_series(1, 1200) as i
) as src
where bp.id = src.id;

/* Stations ------------------------------------------------------------- */
select
  md5('bulk-station:' || i)::uuid,
  'D' || lpad(i::text, 4, '0'),
  s.city || ' ' || s.station_type,
  s.city,
  s.state
from generate_series(1, 1000) as i
cross join lateral (
  select
    (array['Ram','Nan','Vijay','Krishna','Sundar','Dev','Anand','Shiv','Chand','Govind','Hari','Lakshmi','Madhav','Ganga','Yamuna','Kavi','Nava','Raj','Surya','Chandra'])[1 + ((i - 1) / 50)]
      || (array['pur','garh','nagar','patnam','wada','kot','ganj','palli','durg','khera'])[1 + (((i - 1) / 5) % 10)] as city,
    (array['Junction','Central','Halt','Road','Terminus'])[1 + ((i - 1) % 5)] as station_type,
    (array['Delhi','Maharashtra','Karnataka','Tamil Nadu','West Bengal','Gujarat','Rajasthan','Uttar Pradesh','Telangana','Bihar'])[1 + (((i - 1) / 50) % 10)] as state
) as s
on conflict (code) do nothing;

/* Routes and ordered stops --------------------------------------------- */
select
  md5('bulk-route:' || i)::uuid,
  'BULK-' || lpad(i::text, 4, '0'),
  'Demonstration Corridor ' || lpad(i::text, 4, '0'),
  'Synthetic multi-stop corridor generated for load and scale testing.'
from generate_series(1, 1000) as i
on conflict (code) do nothing;

select
  md5('bulk-stop:' || i || ':' || k)::uuid,
  r.id,
  s.id,
  k,
  (k * 70) + ((i % 7) * 5),
  k * 85
from generate_series(1, 1000) as i
cross join generate_series(0, 7) as k
join routes r on r.code = 'BULK-' || lpad(i::text, 4, '0')
join stations s on s.code = 'D' || lpad((((i * 37) + (k * 53)) % 1000 + 1)::text, 4, '0')
on conflict do nothing;

/* Trains and dated runs ------------------------------------------------ */
select
  md5('bulk-train:' || i)::uuid,
  'T' || lpad(i::text, 4, '0'),
  'Bulk Express ' || lpad(i::text, 4, '0'),
  r.id,
  true
from generate_series(1, 1000) as i
join routes r on r.code = 'BULK-' || lpad(i::text, 4, '0')
on conflict (code) do nothing;

select
  md5('bulk-run:' || i || ':' || d || ':' || to_char(b.base_date, 'YYYYMMDD'))::uuid,
  t.id,
  b.base_date + d,
  (b.base_date + d + time '05:00' + make_interval(hours => i % 18)) at time zone 'Asia/Kolkata',
  (b.base_date + d + time '05:00' + make_interval(hours => i % 18) + interval '700 minutes') at time zone 'Asia/Kolkata',
  (case
     when (i + d) % 31 = 0 then 'cancelled'
     when (i + d) % 17 = 0 then 'disrupted'
     else 'scheduled'
   end)::run_status,
  null
from generate_series(1, 1000) as i
cross join generate_series(0, 6) as d
cross join (select (now() at time zone 'Asia/Kolkata')::date as base_date) as b
join trains t on t.code = 'T' || lpad(i::text, 4, '0')
on conflict (train_id, service_date) do nothing;

/* Coaches and seats ---------------------------------------------------- */
select
  md5('bulk-coach:' || i || ':' || d || ':' || c.code)::uuid,
  r.id,
  ct.id,
  c.code,
  c.position,
  c.travel_class::travel_class
from generate_series(1, 1000) as i
cross join generate_series(0, 6) as d
cross join (select (now() at time zone 'Asia/Kolkata')::date as base_date) as b
join trains t on t.code = 'T' || lpad(i::text, 4, '0')
join train_runs r on r.train_id = t.id and r.service_date = b.base_date + d
cross join (values
  ('S1', 'SL72', 'sleeper', 1),
  ('B1', '3A64', 'ac3', 2)
) as c(code, template_code, travel_class, position)
join coach_templates ct on ct.code = c.template_code
on conflict do nothing;

select
  md5('bulk-seat:' || rc.id || ':' || ts.seat_number)::uuid,
  rc.id,
  ts.seat_number,
  ts.berth_type,
  ts.deck,
  ts.row_index,
  ts.position_in_row,
  ts.is_accessible
from run_coaches rc
join train_runs r on r.id = rc.run_id
join trains t on t.id = r.train_id
join template_seats ts on ts.template_id = rc.template_id
where t.code ~ '^T[0-9]{4}$'
on conflict (run_coach_id, seat_number) do nothing;

/* Fares: every stop pair for all four classes -------------------------- */
select
  md5('bulk-fare:' || r.id || ':' || c.travel_class || ':' || a.k || ':' || b.k)::uuid,
  r.id,
  c.travel_class::travel_class,
  a.k,
  b.k,
  greatest(5000, (round(((c.base_paise + c.per_km_paise * ((b.k - a.k) * 70))::numeric) / 500) * 500))::int
from routes r
cross join (values
  ('sleeper', 15000, 35),
  ('ac3', 55000, 90),
  ('ac2', 95000, 140),
  ('chair', 30000, 55)
) as c(travel_class, base_paise, per_km_paise)
cross join generate_series(0, 7) as a(k)
cross join generate_series(0, 7) as b(k)
where r.code like 'BULK-%'
  and b.k > a.k
on conflict do nothing;

/* Demo riders (same password as the seeded accounts) ------------------- */
select
  md5('bulk-user:' || i)::uuid::text,
  'Demo Rider ' || lpad(i::text, 4, '0'),
  'rider' || lpad(i::text, 4, '0') || '@railvyn.demo',
  true,
  now(),
  now()
from generate_series(1, 1000) as i
on conflict (email) do nothing;

select
  md5('bulk-account:' || i)::uuid::text,
  u.id,
  'credential',
  u.id,
  (select a.password from account a where a.provider_id = 'credential' order by a.created_at limit 1),
  now(),
  now()
from generate_series(1, 1000) as i
join "user" u on u.email = 'rider' || lpad(i::text, 4, '0') || '@railvyn.demo'
on conflict (id) do nothing;

select
  md5('bulk-role:' || i)::uuid,
  u.id,
  'passenger',
  now()
from generate_series(1, 1000) as i
join "user" u on u.email = 'rider' || lpad(i::text, 4, '0') || '@railvyn.demo'
on conflict do nothing;

/* Bookings: one per run, plus a second seat on the first 200 runs by
   a different rider, so no rider books the same run twice --------------- */
  id, reference, user_id, run_id, from_stop_index, to_stop_index, travel_class,
  passenger_count, total_fare_paise, status, contact_email, contact_phone,
  idempotency_key, created_at
)
select
  md5('bulk-booking:' || i)::uuid,
  'RVN-B' || lpad(i::text, 6, '0'),
  u.id,
  r.id,
  0,
  1,
  'sleeper',
  1,
  17500,
  'confirmed',
  u.email,
  '+91-90000-' || lpad(i::text, 5, '0'),
  'bulk-booking-' || i,
  now() - make_interval(days => i % 30)
from generate_series(1, 1200) as i
join trains t on t.code = 'T' || lpad((((i - 1) % 1000) + 1)::text, 4, '0')
join train_runs r on r.train_id = t.id
  and r.service_date = (now() at time zone 'Asia/Kolkata')::date
join "user" u on u.email = 'rider' || lpad((case when i <= 1000 then i else i - 500 end)::text, 4, '0') || '@railvyn.demo'
on conflict do nothing;

select
  md5('bulk-bp:' || i)::uuid,
  b.id,
  (array['Aarav','Vivaan','Aditya','Vihaan','Arjun','Sai','Reyansh','Ayaan','Krishna','Ishaan','Shaurya','Atharv','Advik','Pranav','Dhruv','Kabir','Ritvik','Aarush','Kayaan','Darsh','Rudra','Yash','Vedant','Abhinav','Ananya','Diya','Aadhya','Saanvi','Myra','Anika','Navya','Kiara','Aarohi','Ira','Riya','Sara','Nisha','Meera','Kavya','Ishita'])[1 + ((i - 1) % 40)]
    || ' ' ||
  (array['Sharma','Verma','Nair','Rao','Menon','Iyer','Patel','Reddy','Gupta','Singh','Khan','Bose','Kulkarni','Yadav','Mehta','Joshi','Chopra','Desai','Malhotra','Das','Pillai','Shah','Kapoor','Mishra','Ghosh','Shetty','Trivedi','Banerjee','Chauhan','Naidu'])[1 + (((i - 1) / 40) % 30)],
  18 + (i % 55),
  case when ((i - 1) % 40) >= 24 then 'female' else 'male' end,
  1
from generate_series(1, 1200) as i
join bookings b on b.id = md5('bulk-booking:' || i)::uuid
on conflict do nothing;

select
  md5('bulk-bs:' || i)::uuid,
  b.id,
  rs.id,
  bp.id,
  17500
from generate_series(1, 1200) as i
join bookings b on b.id = md5('bulk-booking:' || i)::uuid
join booking_passengers bp on bp.id = md5('bulk-bp:' || i)::uuid
join run_coaches rc on rc.run_id = b.run_id and rc.coach_code = 'S1'
join run_seats rs on rs.run_coach_id = rc.id
  and rs.seat_number = 1 + (((i - 1) / 1000)::int)
on conflict do nothing;

select
  md5('bulk-claim:' || i)::uuid,
  bs.run_seat_id,
  0,
  bs.booking_id,
  now()
from generate_series(1, 1200) as i
join booking_seats bs on bs.id = md5('bulk-bs:' || i)::uuid
on conflict (run_seat_id, segment_index) do nothing;

select
  md5('bulk-payment:' || i)::uuid,
  b.id,
  17500,
  'succeeded',
  'demo_card',
  'bulk-payment-' || i,
  now()
from generate_series(1, 1200) as i
join bookings b on b.id = md5('bulk-booking:' || i)::uuid
on conflict do nothing;

/* Waitlist queue: one request per run, plus a second queue entry from a
   different rider on runs 1-200 so the FIFO demo has two people per run -- */
  id, user_id, run_id, from_stop_index, to_stop_index, travel_class,
  passenger_count, priority, status, created_at, updated_at
)
select
  md5('bulk-wait:' || i)::uuid,
  u.id,
  r.id,
  0,
  1,
  'sleeper',
  1,
  i % 2,
  (array['waiting','offered','expired','cancelled'])[1 + (i % 4)]::waitlist_status,
  now() - make_interval(days => i % 20),
  now()
from generate_series(1, 1200) as i
join trains t on t.code = 'T' || lpad((((i - 1) % 1000) + 1)::text, 4, '0')
join train_runs r on r.train_id = t.id
  and r.service_date = (now() at time zone 'Asia/Kolkata')::date
join "user" u on u.email = 'rider' || lpad((case when i <= 1000 then i else i - 500 end)::text, 4, '0') || '@railvyn.demo'
on conflict do nothing;

/* Expired holds (no live claims, historical records only) -------------- */
  id, user_id, run_id, from_stop_index, to_stop_index, travel_class,
  passenger_count, status, expires_at, idempotency_key, created_at
)
select
  md5('bulk-hold:' || i)::uuid,
  u.id,
  r.id,
  0,
  1,
  'sleeper',
  1,
  'expired',
  now() - make_interval(hours => 6 + (i % 48)),
  'bulk-hold-' || i,
  now() - make_interval(days => 1 + (i % 14))
from generate_series(1, 1000) as i
join trains t on t.code = 'T' || lpad((((i - 1) % 1000) + 1)::text, 4, '0')
join train_runs r on r.train_id = t.id
  and r.service_date = (now() at time zone 'Asia/Kolkata')::date
join "user" u on u.email = 'rider' || lpad((((i - 1) % 1000) + 1)::text, 4, '0') || '@railvyn.demo'
on conflict do nothing;

/* Disruptions and audit trail: one incident per run, unique audit rows -- */
select
  md5('bulk-disruption:' || i)::uuid,
  r.id,
  (array['Signal delay','Rolling stock swap','Weather advisory','Platform change','Track maintenance'])[1 + (i % 5)],
  'Generated demonstration incident ' || lpad(i::text, 4, '0') || ' for ' || t.code
    || ' (' || r.service_date || '): synthetic record for operator workflows and load testing.',
  (array['info','warning','critical'])[1 + (i % 3)]::disruption_severity,
  (select id from "user" where email = 'admin@railvyn.demo'),
  now() - make_interval(days => i % 15),
  case when i % 3 = 0 then now() - make_interval(days => i % 5) else null end
from generate_series(1, 1000) as i
join trains t on t.code = 'T' || lpad(i::text, 4, '0')
join train_runs r on r.train_id = t.id
  and r.service_date = (now() at time zone 'Asia/Kolkata')::date
on conflict do nothing;

select
  md5('bulk-audit:' || i)::uuid,
  (select id from "user" where email = 'admin@railvyn.demo'),
  case when i % 3 = 0 then 'admin' else 'operator' end,
  (array['run.disrupted','booking.cancelled','waitlist.promoted','fare.updated','coach.reassigned'])[1 + (i % 5)],
  'run',
  r.id::text,
  jsonb_build_object('batch', true, 'source', 'bulk-seed', 'sequence', i),
  now() - make_interval(mins => i * 29)
from generate_series(1, 1200) as i
join trains t on t.code = 'T' || lpad((((i - 1) % 1000) + 1)::text, 4, '0')
join train_runs r on r.train_id = t.id
  and r.service_date = (now() at time zone 'Asia/Kolkata')::date
on conflict do nothing;

/* Dense all-pairs network ----------------------------------------------
   The sparse corridors above only connect eight stops each. This block adds
   a synthetic network that guarantees every station pair shares a route:
   stations are split into 20 blocks, every ordered block pair gets a corridor
   (block A stops then block B stops), and each block gets forward/reverse
   local corridors. Pairs inside a block use the local routes; pairs in
   different blocks use the A -> B corridor. */

with station_blocks as (
  select id, code, ntile(20) over (order by code) as block_no
  from stations
),
block_pairs as (
  select a.block_no as block_a, b.block_no as block_b
  from generate_series(1, 20) as a(block_no)
  cross join generate_series(1, 20) as b(block_no)
  where a.block_no <> b.block_no
)
select
  md5('dense-route:' || block_a || ':' || block_b)::uuid,
  'DN-' || lpad(block_a::text, 2, '0') || '-' || lpad(block_b::text, 2, '0'),
  'Dense corridor ' || block_a || ' to ' || block_b,
  'Synthetic all-pairs corridor generated for demonstration searches.'
from block_pairs
on conflict (code) do nothing;

select
  md5('dense-local:' || b.block_no || ':' || d.dir)::uuid,
  'DL-' || lpad(b.block_no::text, 2, '0') || '-' || d.dir,
  'Dense local ' || b.block_no || ' ' || case d.dir when 'F' then 'forward' else 'reverse' end,
  'Synthetic all-pairs corridor generated for demonstration searches.'
from generate_series(1, 20) as b(block_no)
cross join (values ('F'), ('R')) as d(dir)
on conflict (code) do nothing;

with station_blocks as (
  select id, code, ntile(20) over (order by code) as block_no
  from stations
),
cross_order as (
  select
    r.id as route_id,
    sb.id as station_id,
    row_number() over (
      partition by r.id
      order by (sb.block_no = (split_part(r.code, '-', 2))::int) desc, sb.code
    ) as rn
  from routes r
  join station_blocks sb
    on sb.block_no in (
      (split_part(r.code, '-', 2))::int,
      (split_part(r.code, '-', 3))::int
    )
  where r.code like 'DN-%'
)
select
  md5('dense-stop:' || route_id || ':' || station_id)::uuid,
  route_id,
  station_id,
  (rn - 1)::int,
  ((rn - 1) * 20)::int,
  ((rn - 1) * 5)::int
from cross_order
on conflict do nothing;

with station_blocks as (
  select id, code, ntile(20) over (order by code) as block_no
  from stations
),
local_order as (
  select
    r.id as route_id,
    sb.id as station_id,
    row_number() over (
      partition by r.id
      order by
        case when split_part(r.code, '-', 3) = 'F' then sb.code end asc,
        case when split_part(r.code, '-', 3) = 'R' then sb.code end desc
    ) as rn
  from routes r
  join station_blocks sb
    on sb.block_no = (split_part(r.code, '-', 2))::int
  where r.code like 'DL-%'
)
select
  md5('dense-stop:' || route_id || ':' || station_id)::uuid,
  route_id,
  station_id,
  (rn - 1)::int,
  ((rn - 1) * 20)::int,
  ((rn - 1) * 5)::int
from local_order
on conflict do nothing;

select
  md5('dense-train:' || r.code)::uuid,
  'DT' || replace(substr(r.code, 4), '-', ''),
  'Dense Express ' || replace(r.code, '-', ' '),
  r.id,
  true
from routes r
where r.code like 'DN-%' or r.code like 'DL-%'
on conflict (code) do nothing;

with stop_counts as (
  select route_id, count(*)::int as stop_count
  from route_stops
  group by route_id
)
select
  md5('dense-run:' || t.code || ':' || d || ':' || to_char(b.base_date, 'YYYYMMDD'))::uuid,
  t.id,
  b.base_date + d,
  (b.base_date + d + time '06:00' + make_interval(hours => mod(abs(hashtext(t.code)), 11))) at time zone 'Asia/Kolkata',
  (b.base_date + d + time '06:00' + make_interval(hours => mod(abs(hashtext(t.code)), 11))
    + make_interval(mins => (sc.stop_count - 1) * 5)) at time zone 'Asia/Kolkata',
  'scheduled',
  null
from trains t
join stop_counts sc on sc.route_id = t.route_id
cross join generate_series(0, 6) as d
cross join (select (now() at time zone 'Asia/Kolkata')::date as base_date) as b
where t.code like 'DT%'
on conflict (train_id, service_date) do nothing;

select
  md5('dense-coach:' || r.id || ':' || c.code)::uuid,
  r.id,
  ct.id,
  c.code,
  c.position,
  c.travel_class::travel_class
from train_runs r
join trains t on t.id = r.train_id
cross join (values
  ('S1', 'SL72', 'sleeper', 1),
  ('B1', '3A64', 'ac3', 2)
) as c(code, template_code, travel_class, position)
join coach_templates ct on ct.code = c.template_code
where t.code like 'DT%'
on conflict do nothing;

select
  md5('dense-seat:' || rc.id || ':' || ts.seat_number)::uuid,
  rc.id,
  ts.seat_number,
  ts.berth_type,
  ts.deck,
  ts.row_index,
  ts.position_in_row,
  ts.is_accessible
from run_coaches rc
join train_runs r on r.id = rc.run_id
join trains t on t.id = r.train_id
join template_seats ts on ts.template_id = rc.template_id
where t.code like 'DT%'
on conflict (run_coach_id, seat_number) do nothing;

commit;
